import React, { useState, useEffect, useRef, useCallback } from 'react';
import { ToastContainer, toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import Match from './Match';
import html2canvas from 'html2canvas';
import './MatchList.css';
import { AiOutlinePlus, AiOutlineWhatsApp, AiOutlineDelete, AiOutlineInfoCircle, AiOutlineDownload  } from 'react-icons/ai';
import FloatingNotification from '../components/FloatingNotification';
import ReglamentoModal from './ReglamentoModal';

const MatchList = () => {
  const [quinielas, setQuinielas] = useState([]);
  const [username, setUsername] = useState('');
  const inputRef = useRef(null); 
  const gridRef = useRef(null); 
  const addButtonRef = useRef(null);
  const sendButtonRef = useRef(null);
  const [isDoubleTripleEnabled, setIsDoubleTripleEnabled] = useState(false);
  const [currentCost, setCurrentCost] = useState(15);
  const [isReglamentoVisible, setIsReglamentoVisible] = useState(false);
  const [scrollPosition, setScrollPosition] = useState(0);
  const [isWhatsappButtonEnabled, setIsWhatsappButtonEnabled] = useState(false);
  const [results, setResults] = useState({});
  const [selectedResults, setSelectedResults] = useState([]);
  const [notification, setNotification] = useState({ message: '', visible: false, position: 'bottom' });
  

  
  const [matches] = useState([
    {
      id: 1,
      homeTeam: { name: 'Necaxa', logo: process.env.PUBLIC_URL + '/club/Liga-Mx/necaxa.png' },
      awayTeam: { name: 'Querétaro', logo: process.env.PUBLIC_URL + '/club/Liga-Mx/queretaro.png' }
    },
    {
      id: 2,
      homeTeam: { name: 'Mazatlan', logo: process.env.PUBLIC_URL + '/club/Liga-Mx/mazatlan.png' },
      awayTeam: { name: 'Atlas', logo: process.env.PUBLIC_URL + '/club/Liga-Mx/atlas.png' }
    },
    {
      id: 3,
      homeTeam: { name: 'Juárez', logo: process.env.PUBLIC_URL + '/club/Liga-Mx/juarez.png' },
      awayTeam: { name: 'Puebla', logo: process.env.PUBLIC_URL + '/club/Liga-Mx/puebla.png' }
    },
    {
      id: 4,
      homeTeam: { name: 'Toluca', logo: process.env.PUBLIC_URL + '/club/Liga-Mx/toluca.png' },
      awayTeam: { name: 'Pachuca', logo: process.env.PUBLIC_URL + '/club/Liga-Mx/pachuca.png' }
    },
    {
      id: 5,
      homeTeam: { name: 'América', logo: process.env.PUBLIC_URL + '/club/Liga-Mx/america.png' },
      awayTeam: { name: 'Tigres', logo: process.env.PUBLIC_URL + '/club/Liga-Mx/tigres.png' }
    },
    {
      id: 6,
      homeTeam: { name: 'Guadalajara', logo: process.env.PUBLIC_URL + '/club/Liga-Mx/guadalajara.png' },
      awayTeam: { name: 'Cruz Azul', logo: process.env.PUBLIC_URL + '/club/Liga-Mx/cruzazul.png' }
    },
    {
      id: 7,
      homeTeam: { name: 'Monterrey', logo: process.env.PUBLIC_URL + '/club/Liga-Mx/monterrey.png' },
      awayTeam: { name: 'Tijuana', logo: process.env.PUBLIC_URL + '/club/Liga-Mx/tijuana.png' }
    },
    {
      id: 8,
      homeTeam: { name: 'Santos', logo: process.env.PUBLIC_URL + '/club/Liga-Mx/santos.png' },
      awayTeam: { name: 'San Luis', logo: process.env.PUBLIC_URL + '/club/Liga-Mx/atleticosl.png' }
    },
    {
      id: 9,
      homeTeam: { name: 'León', logo: process.env.PUBLIC_URL + '/club/Liga-Mx/leon.png' },
      awayTeam: { name: 'Pumas', logo: process.env.PUBLIC_URL + '/club/Liga-Mx/pumas.png' }
    },
    {
      id: 10,
      homeTeam: { name: 'Napoli', logo: process.env.PUBLIC_URL + '/club/Serie-A/napolis.png' },
      awayTeam: { name: 'Milan', logo: process.env.PUBLIC_URL + '/club/Serie-A/milan.png' }
    },
  ]);

  const handleResultChange = (matchId, result) => {
    let updatedResults = { ...results };
  
    if (isDoubleTripleEnabled) {
      if (updatedResults[matchId] && updatedResults[matchId].includes(result)) {
        updatedResults[matchId] = updatedResults[matchId].filter((r) => r !== result);
      } else {
        updatedResults[matchId] = [...(updatedResults[matchId] || []), result];
      }
    } else {
      updatedResults[matchId] = [result];
    }
  
    setResults(updatedResults);
  
    setSelectedResults((prevSelectedResults) => ({
      ...prevSelectedResults,
      [matchId]: updatedResults[matchId] || [],
    }));
  };
  
 
 const handleCloseNotification = () => {
    setNotification((prevState) => ({ ...prevState, visible: false }));
  };
  
  const showNotification = useCallback(
    (message, position = 'top', elementRef = null, type = 'info') => {
    let customPosition = null;

    if (elementRef) {
        const rect = elementRef.getBoundingClientRect();
        customPosition = {
            top: rect.top + window.scrollY - 30,
            left: rect.left + rect.width / 2 - 100,
        };
    }

    setNotification({ message, visible: true, position, customPosition, type });
}, []);

useEffect(() => {
  if (notification.visible) {
      const timer = setTimeout(() => {
          setNotification((prevState) => ({ ...prevState, visible: false }));
      }, 5000);

      return () => clearTimeout(timer);
  }
}, [notification.visible]);

useEffect(() => {
    if (quinielas.length > 0) {
        setIsWhatsappButtonEnabled(true); 
    } else {
        setIsWhatsappButtonEnabled(false); 
    }
}, [quinielas]);

useEffect(() => {
  const newCost = calculateCost();
  setCurrentCost(newCost);

  showNotification(`Costo actual: $${newCost}`, 'bottom', inputRef.current);
}, [results]); 

const handleSaveQuiniela = () => {
  toast.dismiss();

  if (!username) {
    toast.error('Por favor, ingresa tu nombre antes de guardar la quiniela.');
    return;
  }
  if (Object.keys(results).length !== matches.length) {
    toast.error('Por favor, selecciona un resultado para todos los partidos antes de guardar la quiniela.');
    return;
  }

  const cost = calculateCost();
  const formattedResults = Object.keys(results).reduce((acc, key) => {
    acc[key] = Array.isArray(results[key]) ? results[key] : [results[key]];
    return acc;
  }, {});

  const newQuiniela = { username, results: formattedResults, cost };
  setQuinielas([...quinielas, newQuiniela]);

  // Limpiar el estado después de guardar
  setResults({});
  setSelectedResults([]);

  showNotification('Formulario limpio.', 'bottom');
};

useEffect(() => {
  const savedQuinielas = JSON.parse(localStorage.getItem('quinielas')) || [];
  const savedResults = JSON.parse(localStorage.getItem('results')) || {};
  const savedUsername = localStorage.getItem('username') || '';
  const savedIsDoubleTripleEnabled = JSON.parse(localStorage.getItem('isDoubleTripleEnabled')) || false;

  setQuinielas(savedQuinielas);
  setResults(savedResults);
  setUsername(savedUsername);
  setIsDoubleTripleEnabled(savedIsDoubleTripleEnabled);
}, []);


const isInitialMount = useRef(true);

useEffect(() => {
  if (isInitialMount.current) {
    isInitialMount.current = false;
  } else {
    localStorage.setItem('quinielas', JSON.stringify(quinielas));
  }
}, [quinielas]);

useEffect(() => {
  if (!isInitialMount.current) {
    localStorage.setItem('results', JSON.stringify(results));
  }
}, [results]);

useEffect(() => {
  if (!isInitialMount.current) {
    localStorage.setItem('username', username);
  }
}, [username]);

useEffect(() => {
  if (!isInitialMount.current) {
    localStorage.setItem('isDoubleTripleEnabled', JSON.stringify(isDoubleTripleEnabled));
  }
}, [isDoubleTripleEnabled]);


const handleClear = () => {
  setUsername('');
  setResults({});
  setSelectedResults([]);
  setQuinielas([]);
  toast.dismiss();

  // Limpiar localStorage
  localStorage.removeItem('quinielas');
  localStorage.removeItem('results');
  localStorage.removeItem('username');
  localStorage.removeItem('isDoubleTripleEnabled');
};

  const handleDeleteQuiniela = (index) => {
    const newQuinielas = quinielas.filter((_, i) => i !== index);
    setQuinielas(newQuinielas);
  };

  const handleSendQuinielas = () => {
    const phoneNumber = '525639240505';
    const exportResults = quinielas
      .map((q) => {
        const combinationCount = calculateQuinielas(q.results); 
        return `${q.username}\t${formatResults(q.results)} (${combinationCount})`; 
      })
      .join('\n');
  
    const totalCost = quinielas.reduce((acc, q) => acc + q.cost, 0);
  
    const whatsappMessage = encodeURIComponent(
      `Resultados de las quinielas:\n\n${exportResults}\n\nTotal: $${totalCost}`
    );
    
    const whatsappUrl = `https://wa.me/${phoneNumber}?text=${whatsappMessage}`;
  
    window.open(whatsappUrl, '_blank');
    handleClear();
    toast.info('Quiniela enviadas.');
  };
  
  const formatResults = (results) => {
    return Object.entries(results)
      .map(([matchId, result]) => Array.isArray(result) ? result.join('') : String(result)) 
      .join('  ');
  };
  

  const quinielaCost = 10;
  const totalCost = quinielas.length * quinielaCost;

  useEffect(() => {
    if (!isDoubleTripleEnabled) {
      const updatedResults = {};
      Object.entries(results).forEach(([matchId, selectedResults]) => {
        updatedResults[matchId] = selectedResults.length > 0 ? [selectedResults[0]] : [];
      });
      setResults(updatedResults);
    }
  }, [isDoubleTripleEnabled]);

  useEffect(() => {
    const newCost = calculateCost();
    setCurrentCost(newCost);
    
    showNotification(`Costo actual: $${newCost}`, 'top', inputRef.current);
  }, [results]); 
  
const calculateCost = () => {
  const baseCost = 10;
  let totalCombinations = 1;

  Object.values(results).forEach((selectedResults) => {
    const selectedCount = selectedResults?.length || 0;
    if (selectedCount > 0) {
      totalCombinations *= selectedCount;
    }
  });

  if (Object.keys(results).length < 10) {
    return 0;
  }

  return baseCost * totalCombinations;
};


  const calculateQuinielas = (results) => {
    return Object.values(results).reduce(
      (total, selections) => total * (selections.length || 1),
      1
    );
  };

  const handleOpenReglamento = () => {
    setScrollPosition(window.scrollY);
    setIsReglamentoVisible(true);
  };

  const handleCloseReglamento = () => {
    setIsReglamentoVisible(false);
    window.scrollTo(0, scrollPosition);   
  };

  const handleDownloadImage = async () => {
    const tableElement = gridRef.current;
  
    if (tableElement) {
      try {
        const clonedTable = tableElement.cloneNode(true);
        clonedTable.style.background = '#0a192f'; // Fondo sólido oscuro
        clonedTable.style.backdropFilter = 'none'; // Eliminar el efecto de desenfoque
        clonedTable.style.position = 'fixed';
        clonedTable.style.top = '-9999px'; // Mover la copia fuera de la pantalla
        document.body.appendChild(clonedTable);
  
        const images = clonedTable.querySelectorAll('img');
        const imageLoadPromises = Array.from(images).map((img) => {
          if (!img.complete) {
            return new Promise((resolve) => {
              img.onload = resolve;
              img.onerror = resolve; // Si hay un error, continuar de todos modos
            });
          }
          return Promise.resolve();
        });
  
        await Promise.all(imageLoadPromises);
  
        const canvas = await html2canvas(clonedTable, {
          useCORS: true, // Permitir el uso de imágenes externas
          scale: 2, // Aumentar la resolución de la imagen
          logging: true, // Habilitar logs para depuración
          backgroundColor: '#0a192f', // Fondo sólido oscuro para la imagen
        });
  
        const link = document.createElement('a');
        link.href = canvas.toDataURL('image/png');
        link.download = 'quiniela_partidos.png';
        link.click();
  
        document.body.removeChild(clonedTable);
      } catch (error) {
        console.error('Error al capturar la tabla:', error);
        toast.error('Hubo un error al generar la imagen. Inténtalo de nuevo.');
      }
    }
  };
 
  
  return (
    <div className="quiniela-container">
      <FloatingNotification
        message={notification.message}
        visible={notification.visible}
        position={notification.position}
        customPosition={notification.customPosition}
        onClose={handleCloseNotification}
      />
  
      <ToastContainer limit={2} />

      <section className="match-grid" ref={gridRef}>
        <table className="match-table">
        <thead>
          <tr>
            <th colSpan="3" className="quiniela-header-cell">
              <div className="header-content">
                <span className="header-title">Quiniela Morelia</span>
                <img
                  src={`${process.env.PUBLIC_URL}/Campo-Futbol/logo-quiniela1.png`}
                  alt="Quiniela Morelia Logo"
                  className="header-logo"
                />
              </div>
            </th>
          </tr>
        </thead>
          <tbody>
            {matches.map((match) => (
              <React.Fragment key={match.id}>
                <tr
                  className={`match ${!username ? 'disabled' : ''}`}
                >
   <td
  className={`team ${selectedResults[match.id]?.includes('L') ? 'selected' : ''}`}
  onClick={() => handleResultChange(match.id, 'L')}
>
  <div className="team-content">
    <img src={match.homeTeam.logo} alt={`${match.homeTeam.name} logo`} />
    <span className="team-name">{match.homeTeam.name}</span>
  </div>
</td>
<td
  className={`team ${
    selectedResults[match.id]?.includes('E') ? 'selected' : ''
  }`}
  onClick={() => handleResultChange(match.id, 'E')}
>
  <span>Empate</span>
</td>
<td
  className={`team ${selectedResults[match.id]?.includes('V') ? 'selected' : ''}`}
  onClick={() => handleResultChange(match.id, 'V')}
>
  <div className="team-content">
    <span className="team-name">{match.awayTeam.name}</span>
    <img src={match.awayTeam.logo} alt={`${match.awayTeam.name} logo`} />
  </div>
</td>
                </tr>
              </React.Fragment>
            ))}
          </tbody>
        </table>
      </section>
      
            {/* Información general de la quiniela */}

            {/* <div className="button-container">
        <button onClick={handleDownloadImage} className="download-button">
          <AiOutlineDownload style={{ marginRight: '5px' }} /> Descargar tabla
        </button>
      </div> */}
            <section className="quiniela-info">
        <p>Costo: ${quinielaCost}</p>
        <p>Cierra: Viernes 8:00 pm</p>
      </section>
      
      <section>
      <div className="toggle-double-triple">
        <label>
          <input
            type="checkbox"
            checked={isDoubleTripleEnabled}
            onChange={(e) => setIsDoubleTripleEnabled(e.target.checked)}
          />
          Dobles y triples
        </label>
        <AiOutlineInfoCircle
          style={{ cursor: 'pointer', color: '#ffffff' }}
          title="Información sobre dobles y triples"
          onClick={() =>
            showNotification(
              'Los dobles y triples te permiten seleccionar múltiples resultados por partido. Esto incrementa el costo dependiendo del número de selecciones adicionales.',
              'bottom-right',
              null,
              'success'
            )
          }
        />
      </div>
      </section>
      
      <div className="input-container">
        <input
          ref={inputRef}
          type="text"
          placeholder="Ingresa tu nombre"
          maxLength={30}
          value={username}
          onChange={(e) => setUsername(e.target.value)}
        />
      </div>

      <div ref={addButtonRef} className="button-container">
        <button onClick={handleSaveQuiniela} className="save-button">
          <AiOutlinePlus style={{ marginRight: '5px' }} /> Agregar
        </button>
        {quinielas.length > 0 && (
          <button
            onClick={handleSendQuinielas}
            ref={sendButtonRef}
            className="whatsapp-button"
          >
            <AiOutlineWhatsApp style={{ marginRight: '5px' }} /> Enviar por WhatsApp
          </button>
        )}
        <button onClick={handleClear} className="clear-button">
          <AiOutlineDelete style={{ marginRight: '5px' }} /> Borrar
        </button>
        <div>
  <button onClick={handleOpenReglamento} className="reglamento-button">
    <AiOutlineInfoCircle size={14} /> Reglamento
  </button>
  <ReglamentoModal
    isVisible={isReglamentoVisible}
    onClose={handleCloseReglamento}
  />
</div>
      </div> 
      <section className="result-container">
        <h3>Resultados</h3>
        <p className="total-cost">
          Total acumulado: ${quinielas.reduce((acc, q) => acc + q.cost, 0)}
        </p>
        {quinielas.map((q, index) => (
          <div key={index} className="result-item">
            <p>
              {q.username} - {formatResults(q.results)} - Costo: ${q.cost}
            </p>
            <svg
              xmlns="http://www.w3.org/2000/svg"
              onClick={() => handleDeleteQuiniela(index)}
              fill="none"
              viewBox="0 0 24 24"
              strokeWidth="1.5"
              stroke="currentColor"
              className="delete-icon"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                d="m9.75 9.75 4.5 4.5m0-4.5-4.5 4.5M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z"
              />
            </svg>
          </div>
        ))}
      </section>
    </div>
  );
  
  };
  export default MatchList;
  