import React, { useState, useEffect } from 'react';
import './FloatingNotification.css';

const FloatingNotification = ({ message, visible, position, customPosition, onClose, type = 'info' }) => {
  const [isVisible, setIsVisible] = useState(visible);

  useEffect(() => {
    if (visible) {
      setIsVisible(true); // Mostrar la notificación
    } else {
      // Ocultar la notificación después de la animación
      const timeout = setTimeout(() => setIsVisible(false), 500); // 500ms = duración de la animación
      return () => clearTimeout(timeout);
    }
  }, [visible]);

  const typeStyles = {
    info: { backgroundColor: '#ffcc00', color: '#000' },
  };

  const styles = {
    ...typeStyles[type],
    position: 'fixed',
    top: customPosition?.top || (position === 'top' ? '20px' : 'auto'),
    bottom: customPosition?.bottom || (position === 'bottom' ? '20px' : 'auto'),
    left: customPosition?.left || '50%',
    transform: isVisible ? 'translateX(-50%) scale(1)' : 'translateX(-50%) scale(0.8)',
    zIndex: 9999,
    padding: '15px 25px',
    borderRadius: '10px',
    boxShadow: '0 4px 15px rgba(0, 0, 0, 0.2)',
    fontWeight: 'bold',
    fontSize: '14px',
    opacity: visible ? 1 : 0, // Controlar la opacidad basada en `visible`
    transition: 'all 0.5s ease',
    cursor: 'pointer',
    pointerEvents: visible ? 'auto' : 'none', // Deshabilitar interacción cuando no esté visible
  };

  return (
    <div
      className={`floating-notification ${!visible ? 'hide' : ''}`}
      style={styles}
      onClick={onClose}
    >
      {message}
    </div>
  );
};

export default FloatingNotification;